INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('87afe1e3-8a45-41a5-865f-35ab46cba107', 'table', NULL, '1', 'Defending a programme', 'At your level this is the difference between designing something and keeping it funded through the second budget cycle.', 'I build the case, someone senior defends it', 'I have defended a nine-figure programme to a board myself', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I have defended one, with someone senior in the room', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('4363445e-16be-4c2c-9fb7-80a0ca2ba91a', 'table', NULL, '2', 'Reading the room above you', 'Knowing who actually decides, and what they are quietly afraid of.', 'I present, then find out what happened', 'I know the objection before it is raised', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I usually know who decides, not always what they fear', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('908f9747-d0ef-4ea0-9b5e-6b9155722983', 'table', NULL, '3', 'Making the money case', 'Whether you can put the commercial argument together yourself.', 'I can size a benefit', 'I have built the model the CFO signed', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I have built the case and someone else pressure-tested it', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('6a711bc5-d86f-4e76-bfe5-7ed93b863a5e', 'table', NULL, '4', 'Delivery under real constraints', 'Vendors, legacy systems, procurement — the things that decide whether a plan survives.', 'I plan around them', 'I have rescued one that was already failing', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I have delivered one where the constraints nearly stopped it', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('d8cf10a5-3c15-42f2-b453-1a17d5a452a1', 'table', NULL, '7', 'Building people', 'What happens to the people who work for you afterwards.', 'I run a team well', 'People I trained now run their own', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'People I managed have been promoted', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('33071f85-1186-4591-ba3b-bb524d00094e', 'table', NULL, '8', 'Being called first', 'When in the cycle the phone rings.', 'I get invited when they need capacity', 'I get called before the decision is made', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I am called once the shape of the decision is set', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('fd8f0710-da38-4ac9-adb7-9362efed28dc', 'work', NULL, '1', 'The thing you are asked to explain', 'There is usually one subject people keep coming to you about. This is how firmly you hold it.', 'I know it well enough to do it', 'Senior people come to me before they decide', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'People check with me before they commit', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('6dabe364-dc98-4912-a715-64bc02ba1e7c', 'work', NULL, '2', 'Proof from your own work', 'Whether you can point at something and say this is what happened when I did it.', 'I have worked on good projects', 'I have numbers from my own work I can name', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I can describe the outcome but not the number', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('dfbb9f1a-05d0-4742-b672-7287d2536735', 'work', NULL, '4', 'Finishing what is hard', 'The part of the work everyone else avoids.', 'I deliver what I am given', 'I take the piece nobody wants and close it', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I have finished one nobody wanted', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('25fd8f87-b0cf-4b29-8070-62f7bd648603', 'work', NULL, '7', 'Being trusted with more', 'What happens when something unfamiliar lands.', 'I ask for direction', 'I get handed the new thing because I will figure it out', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I get the new thing when someone senior is watching', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('73be93a8-0036-47ec-80e7-f8e4f6b9f192', 'work', NULL, '8', 'The people who ask for you', 'Whether anyone requests you by name.', 'I get assigned', 'Clients or teams ask for me specifically', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'My own team asks for me', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('4ce077b7-3d28-4e68-a272-574da843455d', 'room', NULL, '1', 'Setting the agenda', 'Whether the direction in your organisation is one you chose.', 'I execute an agenda set elsewhere', 'The agenda is mine and others work to it', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I shape part of the agenda, not all of it', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('df0d6f5c-a55a-4760-8314-13f6f844d727', 'room', NULL, '3', 'Capital and consequence', 'Carrying decisions where the money and the blame are both yours.', 'I recommend, others decide', 'I have made the call and lived with it', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I have made the call with cover from others', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('d7482357-4de7-4c4b-944a-9019ea76631f', 'room', NULL, '5', 'Making other leaders', 'Whether the people you built are running things now.', 'I hire well', 'Several of my people now lead their own organisations', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'People I built now lead functions', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('b0ee13b5-2b1a-4a5c-9cb6-c156b6c00c51', 'room', NULL, '8', 'What outlasts you', 'The part that keeps working when you leave.', 'The results were good', 'What I built still runs without me', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'Something I built is still running, with me in it', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('e7b06136-c54e-4fba-a982-ef810954e4e9', 'work', NULL, '3', 'Being understood by seniors', 'Getting a complicated thing across to someone with four minutes.', 'I have explained it and been asked to repeat it', 'I can land it in one sentence', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I get there, but it takes me two goes', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('d85f6791-5dc3-4c9e-8bd5-9418fee50f10', 'work', NULL, '6', 'Knowing your field beyond your job', 'How far your view reaches past your own projects.', 'I have not looked outside my own projects', 'I can tell you what three competitors are doing wrong', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I know what one or two others are doing', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('11b1c9f7-f9b1-43f0-9b7f-ad194c3164f2', 'table', NULL, '6', 'Where your field is heading', 'Following the direction versus being asked to set it.', 'I read what is published about it', 'I have been asked to shape it', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I am asked what I think about where it is going', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('a59a8dd2-117f-45fc-b739-5416c31b1deb', 'room', NULL, '4', 'Reading the region', 'Policy, regulation and where the ground is shifting in the GCC.', 'I read the announcements when they come out', 'I have been in the room where it changed', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I know who to ask when the ground moves', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('ccbffc33-9695-40ec-8980-8bc4f6785057', 'room', NULL, '7', 'A view worth quoting', 'Whether you hold a position people can name.', 'I have never stated a position publicly', 'People can tell you what I stand for', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'People know roughly where I stand', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('7f7cf213-3d6b-45c3-bb60-2187a25fd168', 'room', NULL, '2', 'Being heard outside your walls', 'How far your view travels beyond people who report to you.', 'My view has stayed inside my organisation', 'Regulators, press and peers ask me first', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'My view travels within my sector, not beyond it', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('9514cdc6-c84f-4c52-8398-98481de20f63', 'table', NULL, '5', 'Turning what you know into words', 'Most of what you know never leaves the room. This is about how much of it does.', 'I have not written any of it down', 'People repeat my argument, sometimes without knowing it came from me', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I have written some of it down for my own team', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('8db71116-a69c-46df-ae82-69c9c50166b6', 'room', NULL, '6', 'Saying the unpopular thing', 'What you do when the room has already agreed.', 'I pick my moments', 'I have taken the harder position where it counted, publicly or in the room', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I have said it privately to the person who mattered', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.capability_dimensions (id,band,sector,position,name,why_line,anchor_low,anchor_high,active,created_at,framework,anchor_mid,instrument_version) VALUES ('e9c42125-5732-490d-b23e-509fe3516eb9', 'work', NULL, '5', 'Saying it in public', 'Whether anything you know exists outside your company.', 'Nothing of mine is public', 'People outside my team read what I write', 'true', '2026-08-10 14:30:38.917462+00', 'BARS (Smith & Kendall 1963) · Leadership Pipeline (Charan) · Miller''s pyramid', 'I have shared something once or twice', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('44c43d0e-62f8-417c-a7b0-daeddc3bb4e0', 'work', NULL, '7', 'Aura found three things you could be known for. Which one is yours?', 'Keep one. Rejecting the others is useful too.', NULL, 'true', '2026-08-10 22:03:55.236606+00', 'proposed', NULL, 'uncontested-space', 'the space nobody else owns', 'You keep one. Aura builds your position on it.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('429d26b0-996d-4e8d-bb2b-215dca826524', 'room', NULL, '7', 'Aura found three positions only you could credibly take. Which one is yours?', 'Keep one. Rejecting the others is useful too.', NULL, 'true', '2026-08-10 22:03:55.236606+00', 'proposed', NULL, 'uncontested-space', 'the space nobody else owns', 'You keep one. Aura builds your position on it.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('cc4039f9-844d-4a76-8342-150106cdbab5', 'room', NULL, '5', 'What do people come to you about that they cannot get elsewhere?', 'In your words. One line is enough.', NULL, 'true', '2026-08-10 22:03:55.236606+00', 'text', NULL, 'owned-territory', 'your 3 subjects', 'Becomes a subject Aura watches for you every night.', 'false', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('b7b3f69f-af83-47bd-8075-b91a6f01bdd5', 'room', NULL, '2', 'When people in your market decide to trust you, what usually did it?', NULL, '[{"label": "I made a hard call and lived with it", "value": "call"}, {"label": "I said the unpopular thing in public", "value": "honest"}, {"label": "I delivered something that is still running", "value": "delivered"}, {"label": "I have said the same thing for years and been right", "value": "consistent"}, {"label": "I gave the credit away", "value": "credit"}, {"label": "I can be told something and it stays with me", "value": "discretion"}]', 'true', '2026-08-10 22:03:55.236606+00', 'multi', '2', 'trust', 'how you build trust', 'Decides how Aura opens a piece so it sounds like you earned it.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('8124cfdf-48c0-449f-99b3-86b08ae3eead', 'room', NULL, '3', 'When you make an argument in public, what is your instinct?', NULL, '[{"label": "Lead with evidence nobody can dispute", "value": "evidence"}, {"label": "Tell what happened, including what it cost", "value": "story"}, {"label": "Reframe the question everyone is asking", "value": "frame"}, {"label": "Name the thing nobody will say", "value": "name"}, {"label": "Take the long view others are too busy for", "value": "long"}, {"label": "Put my own position on the line", "value": "stake"}]', 'true', '2026-08-10 22:03:55.236606+00', 'multi', '2', 'natural-mode', 'your natural tone', 'Decides the shape of what Aura drafts for you.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('16c5e9c0-762c-4e3e-9665-0ddca923c0a1', 'room', NULL, '4', 'How do you sound when it matters?', NULL, '[{"label": "Plain — no decoration", "value": "plain"}, {"label": "Measured — I never overstate", "value": "measured"}, {"label": "Challenging — I want a reaction", "value": "challenging"}, {"label": "Warm — I want people with me", "value": "warm"}, {"label": "Precise — exactness matters", "value": "precise"}, {"label": "I connect it to something larger", "value": "bigger"}]', 'true', '2026-08-10 22:03:55.236606+00', 'multi', '2', 'voice', 'your natural tone', 'Decides your register, so nothing published reads like someone else.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('81780db0-cee2-4dc3-a8ed-9020886d22da', 'table', NULL, '2', 'When someone senior decides to trust you, what usually did it?', NULL, '[{"label": "I delivered something difficult and they saw it", "value": "delivered"}, {"label": "I told them something they did not want to hear", "value": "honest"}, {"label": "I showed numbers they could check", "value": "numbers"}, {"label": "I was steady while others were not", "value": "steady"}, {"label": "I gave the credit away", "value": "credit"}, {"label": "Time — they have watched me for years", "value": "time"}]', 'true', '2026-08-10 22:03:19.199516+00', 'multi', '2', 'trust', 'how you build trust', 'Decides how Aura opens a piece so it sounds like you earned it.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('1c73ba5c-ff5d-473d-8b7d-b8adb702d48c', 'table', NULL, '3', 'When you explain your thinking, what comes naturally?', NULL, '[{"label": "I build a structure people can reuse", "value": "frameworks"}, {"label": "I lead with where I disagree", "value": "contrarian"}, {"label": "I tell what happened on a real piece of work", "value": "stories"}, {"label": "I cut it to the simplest true version", "value": "simplify"}, {"label": "I take people through the numbers", "value": "data"}, {"label": "I ask the question nobody has asked", "value": "question"}]', 'true', '2026-08-10 22:03:19.199516+00', 'multi', '2', 'natural-mode', 'your natural tone', 'Decides the shape of what Aura drafts for you.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('368feb66-1d66-45f2-87ee-be35fff29a4b', 'table', NULL, '4', 'How do you come across when it matters?', NULL, '[{"label": "Direct — I say exactly what I think", "value": "direct"}, {"label": "Measured — I never overstate", "value": "measured"}, {"label": "Challenging — I want people to argue back", "value": "challenging"}, {"label": "Warm — I want people with me", "value": "warm"}, {"label": "Precise — the details matter to me", "value": "precise"}, {"label": "I connect it to something larger", "value": "bigger"}]', 'true', '2026-08-10 22:03:19.199516+00', 'multi', '2', 'voice', 'your natural tone', 'Decides your register, so nothing published reads like someone else.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('b70d38ec-7fb4-48c4-a0df-b288333e3b1f', 'table', NULL, '5', 'What do people come to you about most?', 'In your words. One line is enough.', NULL, 'true', '2026-08-10 22:03:19.199516+00', 'text', NULL, 'owned-territory', 'your 3 subjects', 'Becomes a subject Aura watches for you every night.', 'false', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('590dff34-181f-4202-b2e9-85523546df8a', 'table', NULL, '7', 'Aura found three spaces you could own. Which one is yours?', 'Keep one. Reject the others — rejecting is useful too.', NULL, 'true', '2026-08-10 22:03:19.199516+00', 'proposed', NULL, 'uncontested-space', 'the space nobody else owns', 'You keep one. Aura builds your position on it.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('3abb7d3e-0e00-40fc-9c7c-703a757e8149', 'work', NULL, '2', 'When someone senior started trusting you, what did it?', NULL, '[{"label": "I delivered something hard and they saw it", "value": "delivered"}, {"label": "I said something nobody else would say", "value": "honest"}, {"label": "I showed numbers they could check", "value": "numbers"}, {"label": "I stayed steady when it went wrong", "value": "steady"}, {"label": "I helped without being asked", "value": "help"}, {"label": "Time — they have watched me work", "value": "time"}]', 'true', '2026-08-10 22:03:55.236606+00', 'multi', '2', 'trust', 'how you build trust', 'Decides how Aura opens a piece so it sounds like you earned it.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('bdd8e29f-f41c-41a9-9f52-ee74544fd731', 'work', NULL, '3', 'When you explain your work, what comes naturally?', NULL, '[{"label": "I walk through it step by step", "value": "steps"}, {"label": "I tell what happened on a real job", "value": "story"}, {"label": "I show the numbers", "value": "numbers"}, {"label": "I cut it to the simple version", "value": "simplify"}, {"label": "I compare it to how others do it", "value": "compare"}, {"label": "I point out what usually goes wrong", "value": "warn"}]', 'true', '2026-08-10 22:03:55.236606+00', 'multi', '2', 'natural-mode', 'your natural tone', 'Decides the shape of what Aura drafts for you.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('c03f0eef-df50-4769-bc96-2f4863968329', 'work', NULL, '4', 'How do you come across?', NULL, '[{"label": "Direct — I say what I think", "value": "direct"}, {"label": "Careful — I check before I speak", "value": "careful"}, {"label": "Practical — I stay close to the work", "value": "practical"}, {"label": "Warm — people find me easy to ask", "value": "warm"}, {"label": "Precise — I know the specifics", "value": "precise"}, {"label": "Curious — I ask a lot of questions", "value": "curious"}]', 'true', '2026-08-10 22:03:55.236606+00', 'multi', '2', 'voice', 'your natural tone', 'Decides your register, so nothing published reads like someone else.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('251e52ab-66e0-4765-8e0a-d56c78060c66', 'work', NULL, '9', 'What has stopped you sharing your work publicly?', NULL, '[{"label": "I feel too junior to have a view", "value": "junior"}, {"label": "No time", "value": "time"}, {"label": "I am not sure my employer would like it", "value": "employer"}, {"label": "I do not think it is original enough", "value": "original"}, {"label": "I do not know where to start", "value": "start"}, {"label": "I started but could not keep it going", "value": "momentum"}]', 'true', '2026-08-10 22:03:55.236606+00', 'multi', NULL, 'barrier', 'the honest truth', 'Aura works around this instead of asking you to fix it.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('8a6035a6-2413-45cb-b639-1144b403f962', 'room', NULL, '9', 'What has kept you quiet so far?', NULL, '[{"label": "The position carries real risk", "value": "risk"}, {"label": "No time", "value": "time"}, {"label": "I do not think I have anything new to say", "value": "nothing_new"}, {"label": "Nothing written for me has sounded like me", "value": "voice"}, {"label": "My role makes public positions complicated", "value": "role"}, {"label": "I do not know where to start", "value": "start"}]', 'true', '2026-08-10 22:03:55.236606+00', 'multi', NULL, 'barrier', 'the honest truth', 'Aura works around this instead of asking you to fix it.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('fa0324fb-eb20-4b92-8d2b-76336ffd8937', 'table', NULL, '9', 'What has held you back from being more visible?', NULL, '[{"label": "I do not have time to write consistently", "value": "time"}, {"label": "I do not know what to say that is different", "value": "different"}, {"label": "I am not sure my ideas are original enough", "value": "original"}, {"label": "I worry about what colleagues will think", "value": "colleagues"}, {"label": "I do not know where to start", "value": "start"}, {"label": "I have started but cannot keep it going", "value": "momentum"}]', 'true', '2026-08-10 22:03:19.199516+00', 'multi', NULL, 'barrier', 'the honest truth', 'Aura works around this instead of asking you to fix it.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('297c2927-41fe-4239-bd67-71940315ccc0', 'work', NULL, '8', 'If you had to bet, which are you strongest at?', NULL, '[{"label": "The subject people keep asking me to explain", "value": "explain"}, {"label": "Having proof from my own work", "value": "proof"}, {"label": "Being understood by senior people", "value": "understood"}, {"label": "Finishing what is hard", "value": "hard"}, {"label": "Saying it in public", "value": "public"}, {"label": "Knowing my field beyond my job", "value": "field"}, {"label": "Being trusted with the new thing", "value": "trusted"}, {"label": "People asking for me by name", "value": "asked"}]', 'true', '2026-08-10 22:03:55.236606+00', 'choice', NULL, 'self-claim', 'the honest truth · claim vs evidence', 'Aura checks this against your own posts — the only question that can prove itself wrong.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('77c9d37e-6f53-404b-be93-f846c4cabb91', 'room', NULL, '8', 'If you had to bet, which are you strongest at?', NULL, '[{"label": "Setting the agenda", "value": "agenda"}, {"label": "Being heard outside my own walls", "value": "outside"}, {"label": "Carrying the decision and the consequence", "value": "capital"}, {"label": "Reading where the region is going", "value": "region"}, {"label": "Making other leaders", "value": "leaders"}, {"label": "Saying the unpopular thing", "value": "unpopular"}, {"label": "Holding a view people can name", "value": "view"}, {"label": "Building what outlasts me", "value": "outlast"}]', 'true', '2026-08-10 22:03:55.236606+00', 'choice', NULL, 'self-claim', 'the honest truth · claim vs evidence', 'Aura checks this against your own posts — the only question that can prove itself wrong.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.onboarding_questions (id,band,sector,position,prompt,helper,options,active,created_at,kind,max_choices,framework,feeds,why_asked,allow_none,randomise,instrument_version) VALUES ('c052d907-9f76-4cb0-ba02-4904df27792a', 'table', NULL, '8', 'If you had to bet, which of these are you strongest at?', NULL, '[{"label": "Defending a programme when the money is questioned", "value": "defending"}, {"label": "Reading the room above me", "value": "reading"}, {"label": "Making the commercial case", "value": "money"}, {"label": "Delivery when the constraints are real", "value": "delivery"}, {"label": "Turning what I know into words", "value": "words"}, {"label": "Seeing where the field is heading", "value": "direction"}, {"label": "Building the people around me", "value": "people"}, {"label": "Being called before the decision is made", "value": "called"}]', 'true', '2026-08-10 22:03:19.199516+00', 'choice', NULL, 'self-claim', 'the honest truth · claim vs evidence', 'Aura checks this against your own posts — the only question that can prove itself wrong.', 'true', 'true', '2') ON CONFLICT (id) DO NOTHING;
