INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('c85145d4-db7e-4dce-8c4f-3b99c7221bd6', 'surface_capture', 'Capture', 'Capture adds a source to the vault. It is the only thing that moves capture consistency.', 'surface', 'true', '10', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('59d3d8d4-a163-417c-b8bd-ac5d3dc00b80', 'surface_signals', 'Signals', 'Signals is where strategic signals are read. A signal stays open until it is used or dismissed.', 'surface', 'true', '20', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('b17b3a90-2f83-405b-8b61-37ade6fa808c', 'surface_write', 'Write', 'Write turns a signal or a capture into a draft. Drafting is what moves the content part of the score.', 'surface', 'true', '30', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('194b4723-5e03-46b6-8ff3-016a116d8c37', 'surface_publish', 'Publish', 'Publish puts a draft out. Publishing is the only thing that generates engagement metrics.', 'surface', 'true', '40', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('a536fea9-040b-4ad3-af02-24074ca76662', 'surface_standing', 'Where you stand', 'Where you stand shows the score and its parts, and the capability read.', 'surface', 'true', '50', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('6c6fff67-2acf-48e6-bc55-d9170cb443af', 'score_signal', 'Score: Signal', 'Signal is 40 percent of the score. It reflects how much strategic signal the account is carrying and using.', 'score', 'true', '60', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('4b7b574a-5b15-43d1-ac46-c569edbefe4f', 'score_content', 'Score: Content', 'Content is 40 percent of the score. It reflects drafting and publishing.', 'score', 'true', '70', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('d9489d8c-4f1c-4df9-834e-3f3b50728708', 'capability_save_draft', 'I can save a draft', 'I can write a draft and save it to your drafts. You open it in Publish and it is yours to edit.', 'capability', 'true', '90', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('e2cfaa5b-2262-4d63-a2c8-a0f1b273fa90', 'capability_set_reminder', 'I can set a reminder', 'I can set an in-app reminder for a date you name, up to thirty days out.', 'capability', 'true', '100', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('8cad3323-1ad4-4275-a902-b4191a00771e', 'capability_open_surface', 'I can open a surface', 'I can point you at the surface that holds the answer: Capture, Signals, Write, Publish or Where you stand.', 'capability', 'true', '110', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('c68f2add-533e-407f-a4cb-d4a7dd9f05fc', 'capability_search_vault', 'I can search your vault', 'I can search your own captures, documents, evidence and signals, and cite what I found.', 'capability', 'true', '120', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('23287cb5-949e-43d9-901c-c0f49272b3a6', 'limit_no_linkedin_post', 'I cannot post to LinkedIn', 'I cannot post, schedule or send anything to LinkedIn on your behalf. You publish it yourself.', 'limit', 'true', '130', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('70f5d2ac-5b58-4aa1-b7b9-5c490453075b', 'limit_no_email', 'I cannot send email', 'I cannot send email or message anyone for you.', 'limit', 'true', '140', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('5f5d5012-3e2e-4457-ac5e-52b51da1d32d', 'limit_no_open_web', 'I cannot see the open web', 'I can only see your own graph: your captures, signals, documents and posts. I cannot see the open web, your network, or what anyone else has published.', 'limit', 'true', '150', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:08:53.821951+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.product_facts (id,key,title,body,category,active,sort_order,created_at,updated_at) VALUES ('af5e490c-efc9-43aa-91db-de3b866da3e5', 'score_capture_consistency', 'Score: Capture consistency', 'Capture consistency is 20 percent of the score. It is measured over a rolling eight-week window: each week with at least one capture counts once, and a week with no capture scores zero for that week no matter how much was captured before it.', 'score', 'true', '80', '2026-08-27 15:08:53.821951+00', '2026-08-27 15:14:52.317373+00') ON CONFLICT (id) DO NOTHING;
