INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('67dc2f4d-41e0-4aa5-9b59-32c467d53a46', 'what-is-aura', 'general', 'getting-started', 'What is Aura?', 'Aura turns your expertise into presence. Every week you read, think, and form clear opinions. But most of this stays in your head, and your market never sees it. Aura saves your thinking and helps you share it. So the people who matter see how you think, not only your job title. It works quietly in the background and does not add work to your week.', NULL, '{presence,capture,signal}', '{faq,guide}', '10', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('16f2b545-a5dd-4622-943a-4ce359460389', 'difference-guide-ask-aura', 'general', 'getting-started', 'What is the difference between Guide and Ask Aura?', 'Guide answers questions about Aura itself. For example: what a page does, how your score works, or what a word means. Ask Aura answers questions about your market and your strategy. For example: what to share this week, or what a signal means for you. Simple rule: a question about the app goes to Guide. A question about your market goes to Ask Aura.', NULL, '{}', '{faq,guide}', '20', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('6306ee67-f2ce-4466-8690-4f6b5680b1a5', 'how-to-start', 'general', 'getting-started', 'I just got access — where do I start?', 'Start with one capture. Find an article, post, or report about your field, and save it to Aura. Aura reads it and turns it into a signal: a clear opinion you can share. Three captures in your first week are enough to see how Aura works. The rest grows from there.', NULL, '{capture,signal}', '{faq,guide}', '30', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('3e343b79-df6a-4cbb-8452-7c4422d52237', 'tab-intelligence', 'intelligence', 'tabs', 'What is the Intelligence page for?', 'Intelligence is your radar. It shows the signals Aura built from your captures. You can see which themes you cover, where your gaps are, and what is changing in your field. This is where you decide which topic is worth your opinion.', NULL, '{}', '{faq,guide}', '20', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('7e4e1d0f-c050-4df7-91cf-a3d7b7cf0b63', 'tab-publish', 'publish', 'tabs', 'What is the Publish page for?', 'Publish is where a signal becomes a post you can share. Aura writes a first draft in your own voice — a LinkedIn post, a carousel, or a short memo. It uses the thinking from your captures. You edit it, approve it, and publish it. Nothing is shared without your approval.', NULL, '{}', '{faq,guide}', '30', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('8d783a3a-1801-4115-b4dd-ac9dcb86944e', 'tab-impact', 'impact', 'tabs', 'What is the Impact page for?', 'Impact shows the results of your presence in the market. It tracks how your posts perform and how your reputation grows over time. It also includes the Market Mirror: three outside views of how your market sees you today.', NULL, '{market-mirror}', '{faq,guide}', '40', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('612e6e8a-999d-4b06-abf6-715426565b5e', 'why-these-weights', 'scoring', 'scoring', 'Why is the score split 40 / 40 / 20?', 'Because presence needs all three together. If you capture but never publish, your thinking stays hidden. So signals alone are not enough. If you publish but are not steady, people forget you fast. So content needs a regular rhythm too. The 40/40 keeps capturing and publishing equally important. The 20 keeps you regular.', NULL, '{}', '{faq,guide}', '50', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('0d06f3cc-167f-47d8-93d5-3550f2eb5340', 'term-signal', 'intelligence', 'terms', 'What is a signal?', 'A signal is a clear opinion that you can share, built by Aura from something you captured. It is not a summary of the article. It is your own view: what the article means for your field, and why it matters now. Signals are the starting point for everything you publish.', NULL, '{}', '{tooltip,faq,guide}', '10', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('4e0ac260-716b-4767-810f-2f829b643a29', 'term-capture', 'general', 'terms', 'What does "capture" mean?', 'Capturing means saving something to Aura: an article link, a post, or your own notes. Aura reads it and pulls out the main thinking inside it. It takes only a few seconds and stays fully private. Nothing from a capture is published until you choose to.', NULL, '{}', '{tooltip,faq,guide}', '20', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('db4d14e8-3aa2-4b76-ab61-2618a0ba2bf9', 'tab-home', 'home', 'tabs', 'What is Home?', 'Home is your daily Brief — the first thing you see, made to be read in a minute. It opens with the one tension worth your voice this week, a post already drafted and ready to ship, the signal or two forming on your radar, and a quiet spot to capture whatever you''re reading right now. Most weeks, Home is the only page you need: glance, approve, publish, done.', NULL, '{}', '{faq,guide}', '10', '2026-05-29 22:54:53.404787+00', '2026-07-14 09:39:51.182614+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('fd8d9844-790d-4cb6-96b4-41c018879c18', 'score-overview', 'scoring', 'scoring', 'What is the Imprint?', 'One number out of 100. Signal 40%, content 40%, consistency 20%. Every point comes from a real action you took — and the parts always add up to the total.', 'Imprint = Signal (40%) + Content (40%) + Consistency (20%)', '{signal-strength,content-published,weekly-rhythm}', '{tooltip,faq,guide,hint}', '10', '2026-05-29 22:54:53.404787+00', '2026-06-26 11:05:00.532507+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('4bcedcd6-7ade-4c90-b478-1eb0c0d3e733', 'tab-mystory', 'mystory', 'tabs', 'What is Profile for?', 'Profile is who you are inside Aura — your role, your field, the ground you want to be known for, and where you''re headed. Aura leans on it to keep every signal and every draft close to you. The truer it is, the sharper everything Aura makes for you becomes.', NULL, '{}', '{faq,guide}', '50', '2026-05-29 22:54:53.404787+00', '2026-07-14 09:39:51.182614+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('682e7ce5-15e9-4cc3-be6a-ebd14c1c2e30', 'term-confidence-threshold', 'intelligence', 'terms', 'What is the confidence threshold?', 'Aura checks how strong the support behind each signal is. When a signal has enough support — usually from more than one capture on the same theme — it passes the confidence threshold and becomes ready to publish. If a signal is just below this line, one more related capture is usually enough to pass it.', NULL, '{}', '{tooltip,faq,guide}', '30', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('2d1f7bf4-0527-4b8d-8efe-c9965b64e016', 'term-theme', 'intelligence', 'terms', 'What is a theme?', 'A theme is a topic where you build your presence — for example, one part of your field. Aura groups your signals by theme. This helps you see where you are strong and where you are weak. It is better to cover a few themes well than to spread across many.', NULL, '{}', '{tooltip,faq,guide}', '40', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('c56e0190-6ec9-4ab7-9cc3-491532b207ee', 'howto-capture', 'general', 'how-to', 'How do I capture something?', 'Use the Capture button in the side menu. Paste a link to an article or post, or type your own notes, then save. Aura reads it and builds a signal in a moment. Capture anything that gave you a useful idea this week.', NULL, '{}', '{faq,guide}', '10', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('2d47b84e-4349-4797-b189-c83b541255fa', 'howto-privacy', 'general', 'how-to', 'Is what I capture private?', 'Yes. Your captures and signals belong only to you, and are never shared. Nothing reaches your audience unless you write it, approve it, and publish it yourself. Aura works in private. You decide what becomes public.', NULL, '{}', '{faq,guide}', '40', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('1af961e9-e81d-4c2f-a614-9e63f61fbb1f', 'home-missions', 'home', 'hint', NULL, 'These are your missions for the week. They are the few actions that grow your presence most right now. Doing them is the easiest next step.', NULL, '{}', '{hint}', '20', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('a435ba4a-26b9-43f0-8cc8-1cec3de765d1', 'mystory-profile', 'mystory', 'hint', NULL, 'This is how Aura sees you. The more correct your details here, the better every signal and post Aura builds.', NULL, '{}', '{hint}', '30', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('09f2e68a-f1d6-4877-b108-d67f91c653af', 'intel-radar', 'intelligence', 'hint', NULL, 'Your radar shows which themes you cover and where your gaps are. Weak areas are your next chances to grow.', NULL, '{}', '{hint}', '40', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('6a0e31eb-8b26-4745-a121-cdde35779282', 'intel-signals', 'intelligence', 'hint', NULL, 'These are your signals — the opinions you can share. The ones marked ready have passed the confidence threshold.', NULL, '{}', '{hint}', '50', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('7a7084a3-f939-4d07-8891-1459306e1945', 'publish-create', 'publish', 'hint', NULL, 'Pick a signal that is ready, and Aura writes a post in your own voice. You edit it and approve it. Nothing is published without you.', NULL, '{}', '{hint}', '60', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('15a2bcc7-749a-47ae-ab86-d8be76c464fe', 'impact-score', 'impact', 'hint', NULL, 'This is where you see what your presence is doing in the market over time, and where it is heading.', NULL, '{}', '{hint}', '70', '2026-05-29 22:54:53.404787+00', '2026-05-29 22:54:53.404787+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('2803f3e6-3a31-4551-a76e-73cb6492fd4a', 'tiers', 'scoring', 'scoring', 'What do the tiers (like Explorer) mean?', 'Your tier is a simple label for where you are right now. Everyone starts at Observer. As your score grows you move up — Observer, then Explorer, then Strategist, then Voice, then Presence. Each tier means more of your expertise is visible to your market.', NULL, '{}', '{tooltip,faq,guide}', '60', '2026-05-29 22:54:53.404787+00', '2026-05-30 09:07:42.297184+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('80e8ad59-eae6-4c29-8a52-94d047c1c7a0', 'signal-tier-live', 'signals', 'signals', 'What does the Live tier mean?', 'Strong and fresh. New evidence just reinforced this — it''s the most timely thing you could post right now.', NULL, '{}', '{tooltip}', '100', '2026-06-01 23:36:26.791155+00', '2026-06-01 23:36:26.791155+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('8b065c9c-e150-4a2d-8a56-2ca1c4798e8d', 'signal-tier-evergreen', 'signals', 'signals', 'What does the Evergreen tier mean?', 'A durable strength. Well-evidenced and always worth posting — it simply isn''t tied to this week''s news.', NULL, '{}', '{tooltip}', '101', '2026-06-01 23:36:26.791155+00', '2026-06-01 23:36:26.791155+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('fdcf1e40-ecbf-4bdd-8958-c4f8c6105dfe', 'signal-tier-emerging', 'signals', 'signals', 'What does the Emerging tier mean?', 'Taking shape. A few more captures on this theme and it''ll grow into a strong signal.', NULL, '{}', '{tooltip}', '102', '2026-06-01 23:36:26.791155+00', '2026-06-01 23:36:26.791155+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('eb4fceff-fa2e-4f37-acd4-46ab4169e75a', 'publish-confidence', 'publish', 'tooltip', 'What is publish confidence?', 'A read on how ready THIS draft is to post — hook strength, structure, and how well it carries your signal. It scores the writing in front of you, not the signal itself. Below 70%, Aura offers to strengthen it.', 'Quality score of the current draft, 0–100', '{}', '{publish}', '900', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('b2f82da8-5a29-4407-8fff-9d028412b548', 'home-score', 'home', 'hint', NULL, 'This is your Imprint. It is one number out of 100 that grows as you capture, publish, and stay active. Tap the ? next to it anytime to see the details.', NULL, '{}', '{hint}', '10', '2026-05-29 22:54:53.404787+00', '2026-06-25 13:42:37.47966+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('d2503937-dd15-4b04-8c3b-c070efbbc110', 'howto-improve-score', 'scoring', 'how-to', 'How do I raise my score fastest?', 'Open your Analytics and find the lowest of your three forces — Signal, Content, Consistency. That''s your fastest gain. If Signal is low, capture more sources of different kinds. If Content is low, publish a signal that''s ready. If Consistency is low, just show up — a little each week beats a burst once a month.', NULL, '{}', '{faq,guide}', '30', '2026-05-29 22:54:53.404787+00', '2026-07-14 09:39:51.182614+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('2b695ae6-1f11-45e4-9474-61b5a1d55051', 'strengthen-post', 'publish', 'tooltip', 'What does Strengthen do?', 'Rewrites the draft to fix its weakest parts — a soft hook, a thin middle, a flat close — then re-scores it. The number can move up or down with the new version; you decide which one to keep.', NULL, '{}', '{publish}', '901', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('b19f53aa-6e9f-4093-9d9f-1e38df7f238d', 'post-format', 'publish', 'tooltip', 'What is the format?', 'The shape of the post — how it opens, builds, and lands. Aura picks a format that fits your signal and voice; switch it anytime.', NULL, '{}', '{publish}', '902', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('cb1cc8bf-0cd9-4e30-8027-6f06095e48b8', 'how-built', 'publish', 'tooltip', 'How was this built?', 'Shows the exact capture entries and fragments Aura drew on — so nothing here is generic, and you can trace it back to your own thinking.', NULL, '{}', '{publish}', '903', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('c7d685cf-406c-4eb6-97c7-3ce6aebe8ede', 'variations', 'publish', 'tooltip', 'What are variations?', 'Different takes on the same idea — a sharper hook, a calmer tone, a tighter cut. Pick the one that sounds most like you.', NULL, '{}', '{publish}', '904', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('372cf6c7-78e7-448e-a5fa-e15130f7c1f8', 'save-draft', 'publish', 'tooltip', 'What does Save Draft do?', 'Keeps this in your Library to finish or post later. Nothing goes public until you choose to.', NULL, '{}', '{publish}', '905', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('3a69d046-f6bb-4252-abd6-812900b911c5', 'mark-published', 'publish', 'tooltip', 'What does Mark as published do?', 'Tells Aura you posted this on LinkedIn. It moves to your published archive and starts counting toward your presence.', NULL, '{}', '{publish}', '906', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('6fc68ec9-9210-4565-b7e6-0dd98baeb57a', 'capability-radar', 'mystory', 'tooltip', 'What is the Capability Radar?', 'A map of where your experience is strong and where it is quiet — built from your assessment, not self-reported. It sharpens as Aura learns more about you.', NULL, '{}', '{mystory}', '907', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('26c08e1b-f150-43c9-98fe-47be5fe753e3', 'home-urgent', 'home', 'tooltip', 'What is Urgent?', 'Signals moving right now where a post from you would land hardest this week. Time-sensitive — the window closes as the conversation moves on.', NULL, '{}', '{home}', '908', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('4745025d-5e12-4623-9edf-d161220fb475', 'home-your-moves', 'home', 'tooltip', 'What are Your Moves?', 'The few things that would lift your presence most this week — chosen for impact, not to fill a list.', NULL, '{}', '{home}', '909', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('831896d6-7d97-42af-8bc8-f57d8723358c', 'home-market-scan', 'home', 'tooltip', 'What is Market Scan?', 'A quick read of what your market is talking about today, so you are never posting into a vacuum.', NULL, '{}', '{home}', '910', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('0721bb94-769b-414d-acb1-43d997a8638c', 'intel-territories', 'intelligence', 'tooltip', 'What are Territories?', 'The themes you are building a presence around — the spaces where your name should come up. Each groups the signals you keep returning to.', NULL, '{}', '{intelligence}', '911', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('89767df1-072e-49db-b18f-bca2e9087c95', 'intel-strongest-signal', 'intelligence', 'tooltip', 'What is my strongest signal?', 'The cross-source theme with the most evidence behind it right now — your most defensible thing to say in public.', NULL, '{}', '{intelligence}', '912', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('16bf980b-5b84-4ec9-8e14-29ac74e1c420', 'impact-three-forces', 'impact', 'tooltip', 'What are the three forces?', 'The three things that move your score: the signals you build, the content you publish, and how steadily you show up. Balance beats bursts.', NULL, '{}', '{impact}', '913', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('afb556d3-b5fd-4ce6-abdc-5bde99ac48f2', 'impact-footprint-insight', 'impact', 'tooltip', 'What is this insight?', 'What your numbers are actually saying — in plain terms, with one thing worth doing about it.', NULL, '{}', '{impact}', '915', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('c71752e6-d822-4507-b4ca-40ddef513f99', 'next-tier', 'impact', 'tooltip', 'What is the next tier?', 'What stands between you and the next level — and the smallest, fastest step to get there.', NULL, '{}', '{impact}', '916', '2026-06-02 14:25:20.308971+00', '2026-06-02 14:25:20.308971+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('b3bfe9d6-44a2-4f40-8a0e-641f46845e4d', 'footprint-visibility', 'impact', 'tooltip', 'What is Visibility?', 'How far each post travels — your average impressions per post over the selected period. The wider this is, the more of your market sees you without searching for you.', 'Avg impressions ÷ posts tracked in the period', '{}', '{impact}', '100', '2026-06-02 15:19:05.796151+00', '2026-06-02 15:19:05.796151+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('d23c692d-6975-4bee-968f-f952d7327c51', 'footprint-resonance', 'impact', 'tooltip', 'What is Resonance?', 'How strongly people react once they see you — engagement measured against reach, not raw likes. Read against the benchmark for your follower tier.', 'Engagements ÷ impressions, impression-weighted across the period', '{}', '{impact}', '101', '2026-06-02 15:19:05.796151+00', '2026-06-02 15:19:05.796151+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('33cabe50-331a-4c90-a192-e61699b77f5c', 'footprint-signal-depth', 'impact', 'tooltip', 'What is Signal Depth?', 'How much substance sits behind your presence — how many active signals you are building, and how confident each is. Depth is what separates a voice from noise.', 'Active signals · average confidence %', '{}', '{impact}', '102', '2026-06-02 15:19:05.796151+00', '2026-06-02 15:19:05.796151+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('63a030bd-9d53-43a9-9fee-ebcddbd4ac7e', 'footprint-momentum', 'impact', 'tooltip', 'What is Momentum?', 'Whether you are showing up steadily — how many of the last four weeks had at least one capture. Rhythm beats bursts.', 'Weeks with ≥1 capture, last 4 weeks', '{}', '{impact}', '103', '2026-06-02 15:19:05.796151+00', '2026-06-02 15:19:05.796151+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('c0526194-442d-4c88-a6b1-5fdad0681ff1', 'term-market-mirror', 'impact', 'terms', 'What is Market Mirror?', 'Market Mirror shows how three audiences that matter at your rank read your presence — for a Director: headhunters, CIOs, and curators; for a Partner: clients, your practice, and talent; for the C-suite: boards, peers, and analysts. It refreshes as your signals and posts evolve.', NULL, '{}', '{tooltip,faq,guide}', '50', '2026-05-29 22:54:53.404787+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('9dee53a9-a536-4a7a-b75e-0ca803acc161', 'term-voice-training', 'publish', 'terms', 'What is voice training?', 'Voice training is how Aura learns to write like you, not like AI. It draws from your published posts, anything you teach it, and your own edits. Train it once, then refine: the more real posts it sees, the closer the match.', NULL, '{}', '{tooltip,faq,guide}', '60', '2026-05-29 22:54:53.404787+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('3f167614-70f2-4cb5-82bd-3f52364b0f37', 'impact-footprint', 'impact', 'tooltip', 'What is my LinkedIn footprint?', 'Your real LinkedIn reach — followers, impressions, engagement — pulled straight from your connected LinkedIn account, not estimates.', NULL, '{}', '{impact}', '914', '2026-06-02 14:25:20.308971+00', '2026-07-25 12:28:55.669473+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('dd1724d3-d54c-4734-9405-927e67f5252e', 'voice-signature', 'mystory', 'tooltip', NULL, 'This is how Aura understands the way you write — your tone, the phrases you reach for, the patterns you avoid. The more you teach it, the sharper it gets, and every post Aura drafts uses it so the words sound like you, not like AI.', NULL, '{}', '{}', '0', '2026-06-03 15:11:16.508278+00', '2026-06-03 15:11:16.508278+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('2fa26ed3-2738-4759-ac01-c54dd07dcdb7', 'voice-phrases', 'mystory', 'tooltip', NULL, 'Turns of phrase Aura noticed you use again and again, pulled from your own posts. Seeing your words here is the proof Aura has learned your voice — and it leans on these when it writes for you.', NULL, '{}', '{}', '0', '2026-06-03 15:11:16.508278+00', '2026-06-03 15:11:16.508278+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('b9ec9695-5d19-40dd-9b34-ccf6e2aa0608', 'voice-avoid', 'mystory', 'tooltip', NULL, 'Language you tend to steer clear of. Aura keeps these out of anything it drafts, so nothing reads as generic or off-key for you.', NULL, '{}', '{}', '0', '2026-06-03 15:11:16.508278+00', '2026-06-03 15:11:16.508278+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('6e7d3130-565e-4bbf-b50f-922e0fa05121', 'voice-sharpen', 'mystory', 'tooltip', NULL, 'Re-reads your recent posts and the feedback you''ve given, then refreshes this voice so it keeps up with how you''re writing lately. Use it after you''ve published new posts or taught Aura more.', NULL, '{}', '{}', '0', '2026-06-03 15:11:16.508278+00', '2026-06-03 15:11:16.508278+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('ef17309a-8879-4c1f-8b48-4731fcdffae2', 'term-missions', 'home', 'terms', 'What is This Week''s Rhythm?', 'This Week''s Rhythm shows the few actions that matter most this week — usually one capture, one post, one refinement. Items tick themselves off as you work; there are no points and no streaks. It''s a pulse, not a chore list.', NULL, '{}', '{tooltip,faq,guide}', '70', '2026-05-29 22:54:53.404787+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('8e22f92c-dc7a-49e9-82d0-5875c8284474', 'how-aura-learns-voice', 'mystory', 'how-to', 'How does Aura learn my voice?', 'Aura learns your voice in Arabic and English separately. Your voice card shows a signature for each language — the العربية and English tabs — with a ✦ on your primary voice, the language you publish in most ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('ba2892d0-6ede-4f8e-8af9-bdd962a3788f', 'howto-publish', 'publish', 'how-to', 'How do I publish a post?', 'Open a draft, make it yours, then Mark as published. Aura asks for the post''s LinkedIn link — optional, but pasting it lets Aura track how the post performs and learn from it. Published posts move to your Library under Published, and their engagement feeds your score.', NULL, '{}', '{faq,guide}', '20', '2026-05-29 22:54:53.404787+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('e541191b-7387-41ee-a976-a5aa55891895', 'data-privacy', 'settings', 'trust', 'Your data, and who can see it', 'What Aura keeps: the articles and notes you capture, the LinkedIn analytics Aura syncs from your connected account, your assessment answers, and the signals Aura builds from them ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('552dd505-9b8f-4a67-b1ea-88c70d3780f4', 'howto-edit-drafts', 'publish', 'how-to', 'How do I edit a draft?', 'Open any draft — from Home''s weekly card or the Library pencil — and it loads in Create. Tap the pencil on the preview to edit the text directly, then Done and Save draft. Your edit is saved to the same draft, and the preview updates everywhere it appears.', NULL, '{}', '{faq,guide}', '25', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('f4d46aa7-b213-47d9-87aa-73a3581d15e2', 'term-primary-voice', 'mystory', 'terms', 'What does "primary voice" mean?', 'Your primary voice is the language Aura writes in by default — marked with ✦ on your voice card. It''s set by your recent posts, not by a setting: publish mostly in Arabic, and Arabic leads. If it ever changes, Aura tells you on the card.', NULL, '{}', '{faq,guide}', '60', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('728b15a3-d27f-489e-9c92-32961497723e', 'howto-settings', 'settings', 'how-to', 'What can I manage in Settings?', 'Settings holds your account, appearance, and notification preferences, plus your data controls — including export and deletion. It''s also where you''ll find a link to this guide.', NULL, '{}', '{faq,guide}', '10', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('7da3303d-2a6f-4f93-9449-e8023dae8813', 'identity-report', 'settings', 'how-to', 'What is the Strategic Identity Report?', 'A branded PDF of your professional identity: your score and how it''s built, your strongest signals, and how the market reads you. Export it from Settings and use it where presence matters — before a panel, a board introduction, or a search conversation.', NULL, '{}', '{faq,guide}', '80', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('49657047-ee6f-46a6-a6c3-4a75e2256e9e', 'howto-ask-aura', 'general', 'how-to', 'How do I use Ask Aura?', 'Ask Aura is your chief of staff. Ask it anything about your signals, your market, or your next move — or use the quick actions: LinkedIn Post, Identify Gaps, Draft Memo, Meeting Prep, Draft Deck, Synthesize, and Market Mirror. Every answer is grounded in your own signals and ends with a next step.', NULL, '{}', '{faq,guide}', '50', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('ce89b61a-8d8f-434e-90f9-baccd6586d00', 'tip-separate-posts', 'general', 'tips', 'Teaching several posts at once', 'When pasting more than one post into "Teach Aura your writing", put --- on its own line between posts. That''s how Aura knows where one post ends and the next begins — and files each one in the right language.', NULL, '{}', '{faq,guide}', '10', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('3c8e86fc-9499-45f9-ba27-73d8c6893f73', 'tip-own-the-tone', 'general', 'tips', 'Make the signature line yours', 'The signature line on your voice card is yours. Edit it once to say exactly who you are — Aura will sharpen everything around it, but it will never rewrite your words.', NULL, '{}', '{faq,guide}', '20', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('6d15c2be-f644-48f7-a043-a64621baa7d9', 'tip-paste-the-link', 'general', 'tips', 'Always paste the post link', 'After publishing on LinkedIn, paste the post''s link when you mark it published. It takes five seconds, and it lets Aura track the post and learn what works for you.', NULL, '{}', '{faq,guide}', '30', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('7af6dce0-75de-42f5-be0c-1010ce4425d7', 'tip-monday-quarter-hour', 'general', 'tips', 'Fifteen minutes on Monday', 'Fifteen minutes on Monday is enough: open Home, read your three drafts, sharpen the one you like most, ship it. Consistency beats volume — the score is built that way.', NULL, '{}', '{faq,guide}', '40', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('25a975cf-2ea8-4437-a67c-b7654ccf7ed9', 'tip-capture-breadth', 'general', 'tips', 'Capture from different places', 'Signals grow from breadth and depth: a few capture entries from different organizations beat many from the same one. When something makes you think, capture it — Aura does the connecting.', NULL, '{}', '{faq,guide}', '50', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('8990d576-cc3b-4247-9825-768ae95f108f', 'faq-draft-languages', 'publish', 'how-to', 'Why are my weekly drafts in Arabic and English?', 'The mix follows your behavior. Aura looks at your last 30 posts: your main language fills most slots, and your second language earns one when it''s at least a quarter of what you publish. Change what you post, and the mix follows.', NULL, '{}', '{faq,guide}', '28', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('266cb6ad-a66e-415e-909a-5439c75a2d02', 'faq-primary-changed', 'mystory', 'how-to', 'Why did my primary voice change?', 'Because your recent posts changed. Primary voice follows what you actually publish. When it switches, Aura posts a notice on your voice card — dismiss it once you''ve seen it. Your signatures for both languages are kept either way.', NULL, '{}', '{faq,guide}', '58', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('92f0c4d6-661d-430c-90fe-55e16541ecbd', 'faq-delete-capture', 'intelligence', 'how-to', 'What happens if I delete a capture entry?', 'Its evidence is removed and any signal that referenced it drops that evidence and recounts. Signals supported by your other entries stay; nothing else is touched.', NULL, '{}', '{faq,guide}', '60', '2026-06-05 08:20:34.682198+00', '2026-06-05 08:20:34.682198+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('ecb0f717-868b-4e4c-abde-05a5aff8c7b1', 'signals-overview', 'intelligence', 'signals', 'What do the signal states mean?', 'Every signal Aura builds carries a state that tells you how ready it is to publish from. The state changes on its own as you capture more and as your themes heat up or cool down — you never set it by hand.', NULL, '{}', '{faq,guide}', '10', '2026-06-26 11:05:23.543658+00', '2026-06-26 11:05:23.543658+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('70551b64-62a3-41d7-9748-4e2ee36c0489', 'signal-live', 'intelligence', 'signals', 'What is a live signal?', 'A signal that is active right now — recent captures keep feeding it and the market is moving on the same theme. Live signals are your strongest material to publish this week, while the moment is still open.', NULL, '{}', '{faq,guide}', '20', '2026-06-26 11:05:23.543658+00', '2026-06-26 11:05:23.543658+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('0f044d52-9640-4396-9d6b-972af754c9d0', 'signal-evergreen', 'intelligence', 'signals', 'What is an evergreen signal?', 'A signal that stays useful long after you first built it. The theme does not fade with the news cycle, so you can publish from it any time and it still lands.', NULL, '{}', '{faq,guide}', '30', '2026-06-26 11:05:23.543658+00', '2026-06-26 11:05:23.543658+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('2087ef5d-5056-4458-af21-875b84d8929a', 'signal-emerging', 'intelligence', 'signals', 'What is an emerging signal?', 'A signal that is still forming. You have captured a thread or two on the theme, but it is not strong enough yet to carry a post on its own. Capture a little more and it can grow into a live signal.', NULL, '{}', '{faq,guide}', '40', '2026-06-26 11:05:23.543658+00', '2026-06-26 11:05:23.543658+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('7b324562-3822-4c56-9f4e-60a0ab779fb3', 'signal-faded', 'intelligence', 'signals', 'What is a faded signal?', 'A signal that has gone quiet — no recent captures, and the theme has cooled. It is not gone: a fresh capture on the same theme can bring it back. Until then, Aura keeps it out of your way.', NULL, '{}', '{faq,guide}', '50', '2026-06-26 11:05:23.543658+00', '2026-06-26 11:05:23.543658+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('3a60c909-04a6-40e2-bafd-f4cca2ee4319', 'your-week-ready', 'home', 'how-to', 'What is "Your week, ready"?', 'Every Monday morning, before you''ve had your coffee, Aura prepares up to three drafts from your strongest signals — in the languages you actually publish in. Home opens with one, ready to make yours and ship; the rest wait in your drafts for when you want them. You bring the judgment; Aura does the blank-page work for you.', NULL, '{}', '{faq,guide}', '20', '2026-06-05 08:20:34.682198+00', '2026-07-14 09:39:51.182614+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('48244d9d-c7f4-431d-a65a-e455ea8c0a7e', 'imprint', 'scoring', 'scoring', 'How is my Imprint calculated?', 'How visible your expertise is, from 0 to 100. It rises as you read and publish.', 'Imprint = Signal (40%) + Content (40%) + Consistency (20%). Each part scores 0–100; the weighted blend is your Imprint.', '{signal-strength,content-published,weekly-rhythm}', '{tooltip,faq,guide}', '11', '2026-07-14 09:40:23.949405+00', '2026-07-14 09:40:23.949405+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('6182ec78-a7ee-40c2-ab6d-33382a8da986', 'imprint-composition', 'scoring', 'scoring', 'What builds my Imprint?', 'Your Imprint is built from three things: the strength of your signals, what you have published, and how steadily you show up.', 'Imprint = Signal (40%) + Content (40%) + Consistency (20%). Each part scores 0–100; the weighted blend is your Imprint.', '{signal-strength,content-published,weekly-rhythm}', '{tooltip,faq,guide}', '12', '2026-07-14 09:40:23.949405+00', '2026-07-14 09:40:23.949405+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('e6175a2b-aaa4-4632-a928-e4c8f9d0fbda', 'imprint-facets', 'scoring', 'scoring', 'What are the seven facets?', 'The seven sides of your standing — Identity, Expertise, Voice, Focus, Audience, Perception, and Confidence. A fuller shape means a rounder presence. Facets are a diagnostic view of where you are strong or still forming; they do not change the Imprint number itself.', NULL, '{}', '{tooltip,faq,guide}', '13', '2026-07-14 09:40:23.949405+00', '2026-07-14 09:40:23.949405+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('12cf9a2f-4691-4bdb-816a-a2ead360270c', 'signal-strength', 'scoring', 'scoring', 'What does Signal measure?', 'How solid your captured thinking is, how wide it ranges, and how alive it is right now.', 'Signal (0–100) = Depth (up to 60) + Breadth (up to 30) + Liveness (up to 10). Depth = the strength and evidence behind your signals (live & evergreen ones count most); Breadth = how many distinct themes they span (rises fast, then levels off); Liveness = the share of your strength in still-live themes. Signal counts 40% toward your Imprint — e.g. 75/100 → 30 of 40.', '{signal,confidence-threshold,theme}', '{tooltip,faq,guide}', '20', '2026-05-29 22:54:53.404787+00', '2026-07-14 11:43:09.135957+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('335d3cdf-5387-4067-9a46-1f00e542f6a3', 'content-published', 'scoring', 'scoring', 'What does Content measure?', 'How much of your thinking you actually shared — and whether the market responded. Quality counts more than volume: posting more stops helping after a point.', 'Content (0–100) = Foundation (up to 15, from your imported history) + Published (up to 85, how much you''ve posted in the last 30 days on a curve that levels off after a handful) × Quality (×0.7 to ×1.3, your recent engagement vs your own 12-month median). Content counts 40% toward your Imprint.', '{}', '{tooltip,faq,guide}', '30', '2026-05-29 22:54:53.404787+00', '2026-07-14 11:43:09.135957+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('2a92fe3b-83bf-430b-a56a-6d377987267c', 'weekly-rhythm', 'scoring', 'scoring', 'What is Consistency, and why does being regular matter more than how much you post?', 'Your weekly habit, not your total output. Showing up a little each week beats posting a lot and going quiet. It is 20% of your score.', 'Consistency (0–100) = (active weeks in the last 4 ÷ 4 × 60%) + (active weeks in the last 12 ÷ 12 × 40%), ×100. A week counts if you captured at least once — volume doesn''t matter, showing up does; your last 4 weeks weigh most. Consistency counts 20% toward your Imprint — e.g. 80/100 → 16 of 20.', '{}', '{tooltip,faq,guide}', '40', '2026-05-29 22:54:53.404787+00', '2026-07-14 11:43:09.135957+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.guide_articles (id,slug,tab,category,question_en,answer_en,formula_note_en,related_terms,surfaces,sort_order,created_at,updated_at) VALUES ('a9538b43-d10c-4269-b3bf-8339583b9e2c', 'impact-briefing', 'impact', 'tooltip', NULL, 'An honest read of your LinkedIn presence this period — generated from your live LinkedIn analytics, not guesswork. The numbers are yours; the reading is Aura''s.', NULL, '{}', '{}', '0', '2026-06-02 21:01:54.200846+00', '2026-07-25 12:28:55.669473+00') ON CONFLICT (id) DO NOTHING;
